<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\CandidateProfile;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;
class CandidateCvShareController extends Controller{public function update(Request $request):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);$data=$request->validate(['enabled'=>['required','boolean']]);$profile=$request->user()->candidateProfile;abort_unless($profile,422,'Completa primero tu perfil.');$profile->update(['public_cv_enabled'=>$data['enabled'],'public_cv_token'=>$profile->public_cv_token??(string)Str::uuid()]);return response()->json(['data'=>['enabled'=>$profile->public_cv_enabled,'url'=>$profile->public_cv_enabled?rtrim(config('app.frontend_url'),'/').'/cv/'.$profile->public_cv_token:null],'message'=>$profile->public_cv_enabled?'Enlace público activado.':'Enlace público desactivado.']);}public function show(string $token):JsonResponse{$profile=CandidateProfile::with('user:id,name,email,phone')->where('public_cv_token',$token)->where('public_cv_enabled',true)->firstOrFail();return response()->json(['data'=>['name'=>$profile->user->name,'professional_title'=>$profile->professional_title,'summary'=>$profile->summary,'province'=>$profile->province,'city'=>$profile->city,'skills'=>$profile->skills,'languages'=>$profile->languages,'experience'=>$profile->experience,'education'=>$profile->education,'certifications'=>$profile->certifications,'portfolio_url'=>$profile->portfolio_url]]);}}
